TransactionImportReport = {
    init: async function(app, container, flowData) {
        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
        var data = JSON.parse(await api.get("DMS/Data/Transactions/Processed/" + flowData.LastUpdated + "/Report-" + flowData.FlowDefinitionId + ".json"));

        var generateStatHtml = function(section, html) {
            html += "<li><label>[resource_displayname[NewlyImported]]</label><div class='value'>" + section.NewlyImported + "</div></li>";
            html += "<li><label>[resource_displayname[FailuresTotal]]</label><div class='value'>" + section.FailuresTotal + "</div></li>";
            html += "<li><label>[resource_displayname[UpdatesTotal]]</label><div class='value'>" + section.UpdatesTotal + "</div></li>";
            html += "<li><label>[resource_displayname[UpdatesSucceeded]]</label><div class='value'>" + section.UpdateSucceeded + "</div></li>";
            return html;
        };
        var statisticsHtml = "";
        statisticsHtml = generateStatHtml(data.Invoices, statisticsHtml);
        statisticsHtml = generateStatHtml(data.Credits, statisticsHtml);
        statisticsHtml = generateStatHtml(data.Payments, statisticsHtml);
        $("[name=statisticsData]", container).html(statisticsHtml);

    }
}
